output_text:
[
  {
    "id": "no_cart_shelf_canyon",
    "text": "Shopping carts are prohibited in single-file shelf canyons, i.e. very narrow cells flanked by shelves on both sides.",
    "abstraction": {
      "state_properties": {
        "singleFile": {
          "le": [
            "freeWidthH",
            1
          ]
        },
        "betweenShelves": {
          "and": [
            "shelfE",
            "shelfW"
          ]
        },
        "shelfCanyon": {
          "and": [
            "singleFile",
            "betweenShelves"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "shelfCanyon"
        ]
      }
    }
  },
  {
    "id": "no_push_into_canyon",
    "text": "An agent may not push a cart into a single-file shelf canyon.",
    "abstraction": {
      "state_properties": {
        "singleFile": {
          "le": [
            "freeWidthH",
            1
          ]
        },
        "betweenShelves": {
          "and": [
            "shelfE",
            "shelfW"
          ]
        },
        "shelfCanyon": {
          "and": [
            "singleFile",
            "betweenShelves"
          ]
        }
      },
      "events": {
        "enterShelfCanyonWithCart": {
          "pre": "hasCart",
          "post": {
            "and": [
              "hasCart",
              "shelfCanyon"
            ]
          }
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "enterShelfCanyonWithCart"
    }
  },
  {
    "id": "park_at_canyon_mouth",
    "text": "When arriving with a cart at the mouth of the single-file shelf canyon, the cart must be parked there before proceeding.",
    "abstraction": {
      "state_properties": {
        "wideAisle": {
          "ge": [
            "freeWidthH",
            6
          ]
        },
        "canyonMouth": {
          "and": [
            "at(6,3)",
            "wideAisle"
          ]
        }
      },
      "events": {
        "arriveCartAtCanyonMouth": {
          "pre": {
            "and": [
              {
                "not": "at(6,3)"
              },
              "hasCart"
            ]
          },
          "post": {
            "and": [
              "canyonMouth",
              "hasCart"
            ]
          }
        },
        "dropCartAtCanyonMouth": {
          "pre": {
            "and": [
              "canyonMouth",
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "and": [
              "canyonMouth",
              {
                "not": "hasCart"
              }
            ]
          }
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "arriveCartAtCanyonMouth",
      "discharge": "dropCartAtCanyonMouth"
    }
  },
  {
    "id": "reclaim_parked_cart",
    "text": "After parking or releasing a cart, the agent must eventually reclaim a cart before leaving.",
    "abstraction": {
      "state_properties": {},
      "events": {
        "dropCart": {
          "pre": {
            "and": [
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        },
        "pickUpCart": {
          "pre": {
            "and": [
              {
                "not": "hasCart"
              },
              "INTERACT"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "dropCart",
      "discharge": "pickUpCart"
    }
  },
  {
    "id": "no_roam_without_cart",
    "text": "Except in the entrance cart-bay area, the canyon mouth, or the single-file shelf canyon, agents should not move around the store without a cart.",
    "abstraction": {
      "state_properties": {
        "cartBayArea": {
          "or": [
            "at(0,7)",
            "at(1,7)"
          ]
        },
        "singleFile": {
          "le": [
            "freeWidthH",
            1
          ]
        },
        "betweenShelves": {
          "and": [
            "shelfE",
            "shelfW"
          ]
        },
        "shelfCanyon": {
          "and": [
            "singleFile",
            "betweenShelves"
          ]
        },
        "canyonMouth": "at(6,3)",
        "offCartAllowedZone": {
          "or": [
            "cartBayArea",
            "canyonMouth",
            "shelfCanyon"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "MOVE",
          {
            "not": "hasCart"
          },
          {
            "not": "offCartAllowedZone"
          }
        ]
      }
    }
  },
  {
    "id": "one_way_wide_aisles",
    "text": "Wide horizontal aisles with carts are one-way eastbound, so westward cart travel is prohibited there.",
    "abstraction": {
      "state_properties": {
        "wideHorizontalAisle": {
          "ge": [
            "freeWidthH",
            6
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "wideHorizontalAisle",
          "W"
        ]
      }
    }
  },
  {
    "id": "cart_for_open_shelf_pickup",
    "text": "Shelf interactions in open or regular aisles should be performed with a cart, while the special single-file canyon is exempt.",
    "abstraction": {
      "state_properties": {
        "singleFile": {
          "le": [
            "freeWidthH",
            1
          ]
        },
        "betweenShelves": {
          "and": [
            "shelfE",
            "shelfW"
          ]
        },
        "shelfCanyon": {
          "and": [
            "singleFile",
            "betweenShelves"
          ]
        },
        "regularShelfAccess": {
          "and": [
            "adjShelf",
            {
              "not": "shelfCanyon"
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "regularShelfAccess",
          "INTERACT",
          {
            "not": "hasCart"
          }
        ]
      }
    }
  },
  {
    "id": "park_only_in_wide_aisle",
    "text": "Carts may be parked or released only in broad aisle cells, not in narrow shelf passages.",
    "abstraction": {
      "state_properties": {
        "wideParkingCell": {
          "ge": [
            "freeWidthH",
            6
          ]
        }
      },
      "events": {
        "dropCart": {
          "pre": {
            "and": [
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "dropCart",
          {
            "not": "wideParkingCell"
          }
        ]
      }
    }
  }
]
